const motion=document.querySelector('#motion'),preference=matchMedia('(prefers-reduced-motion: reduce)');let reduced=preference.matches;
function applyMotion(){document.documentElement.classList.toggle('reduced',reduced);document.documentElement.classList.toggle('js-motion',!reduced);document.documentElement.classList.toggle('motion-enabled',!reduced);motion.setAttribute('aria-pressed',String(reduced));motion.textContent=reduced?'Enable motion':'Reduce motion'}applyMotion();motion.addEventListener('click',()=>{reduced=!reduced;applyMotion()});preference.addEventListener('change',e=>{reduced=e.matches;applyMotion()});
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.06});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));
// The confirmed date is used until the organizer supplies the exact start time.
const eventStart='2026-10-15T00:00:00+05:30';
function countdown(){const remaining=Math.max(0,Date.parse(eventStart)-Date.now()),seconds=Math.floor(remaining/1000),values={days:Math.floor(seconds/86400),hours:Math.floor(seconds/3600)%24,minutes:Math.floor(seconds/60)%60,seconds:seconds%60};for(const [id,value] of Object.entries(values))document.getElementById(id).textContent=String(value).padStart(2,'0');if(!remaining){document.getElementById('countdown-heading').textContent='Event day has arrived';document.getElementById('countdown-note').textContent='Contact a coordinator for the event status.'}}countdown();setInterval(countdown,1000);
const cursor=document.querySelector('.cad-cursor');let mouseX=0,mouseY=0,queued=false;
document.addEventListener('pointermove',e=>{if(e.pointerType!=='mouse'||reduced)return;mouseX=e.clientX;mouseY=e.clientY;if(!queued){queued=true;requestAnimationFrame(()=>{cursor.style.left=mouseX+'px';cursor.style.top=mouseY+'px';queued=false})}cursor.classList.toggle('hover',Boolean(e.target.closest('a,button,summary,input')))});
document.addEventListener('pointerdown',e=>{if(reduced||e.button!==0)return;const ripple=document.createElement('span');ripple.className='touch-ripple';ripple.style.left=e.clientX+'px';ripple.style.top=e.clientY+'px';document.body.appendChild(ripple);ripple.addEventListener('animationend',()=>ripple.remove(),{once:true});setTimeout(()=>ripple.remove(),700)});
document.addEventListener('pointerleave',()=>{cursor.style.opacity='0'});document.addEventListener('pointerenter',()=>{cursor.style.opacity=''});

// Count live page views using a shared hosted counter; local previews do not count.
const visitorCounter=document.getElementById('visitor-counter'),visitorStatus=document.getElementById('visitor-status');
if(location.protocol==='https:'&&!['localhost','127.0.0.1','::1'].includes(location.hostname)){visitorCounter.addEventListener('load',()=>{visitorCounter.hidden=false;visitorStatus.hidden=true});visitorCounter.addEventListener('error',()=>{visitorStatus.textContent='Counter temporarily unavailable.'});visitorCounter.src=visitorCounter.dataset.counterSrc;}
